import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { projectLogic } from 'scenes/projectLogic'

import { tasksMeConfigTaskDefaultsCreate } from 'products/tasks/frontend/generated/api'
import type {
    TasksTaskDefaultsApi,
    TasksTaskDefaultsUpdateApi,
    TasksUserConfigResponseApi,
} from 'products/tasks/frontend/generated/api.schemas'

import { taskRunDefaultsLogic } from './taskRunDefaultsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskDefaultsLogicValues {
    currentProjectId: number | null // projectLogic
    myConfig: TasksUserConfigResponseApi | null // taskRunDefaultsLogic
    myConfigLoading: boolean // taskRunDefaultsLogic
    lastTaskDefaults: TasksTaskDefaultsApi | null
    taskDefaults: TasksTaskDefaultsApi | null
    taskDefaultsSaving: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskDefaultsLogicActions {
    loadMyConfig: () => any // taskRunDefaultsLogic
    loadMyConfigSuccess: (
        myConfig: TasksUserConfigResponseApi | null,
        payload?: any
    ) => {
        myConfig: TasksUserConfigResponseApi | null
        payload?: any
    } // taskRunDefaultsLogic
    saveTaskDefaults: (changes: TasksTaskDefaultsUpdateApi) => {
        changes: TasksTaskDefaultsUpdateApi
    }
    saveTaskDefaultsDone: (saved: TasksTaskDefaultsApi | null) => {
        saved: TasksTaskDefaultsApi | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskDefaultsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        taskDefaults: (
            lastTaskDefaults: TasksTaskDefaultsApi | null,
            myConfig: TasksUserConfigResponseApi | null
        ) => TasksTaskDefaultsApi | null
    }
}

export type taskDefaultsLogicType = MakeLogicType<
    taskDefaultsLogicValues,
    taskDefaultsLogicActions,
    Record<string, any>,
    taskDefaultsLogicMeta
>

/**
 * The person's defaults for new tasks in this project. They come with the tasks config that
 * taskRunDefaultsLogic already loads, so reading them needs no extra request.
 */
export const taskDefaultsLogic = kea<taskDefaultsLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'taskDefaultsLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId'], taskRunDefaultsLogic, ['myConfig', 'myConfigLoading']],
        actions: [taskRunDefaultsLogic, ['loadMyConfig', 'loadMyConfigSuccess']],
    })),
    actions({
        saveTaskDefaults: (changes: TasksTaskDefaultsUpdateApi) => ({ changes }),
        saveTaskDefaultsDone: (saved: TasksTaskDefaultsApi | null) => ({ saved }),
    }),
    reducers({
        // A failed reload clears myConfig, so keep the last values the server returned.
        lastTaskDefaults: [
            null as TasksTaskDefaultsApi | null,
            {
                loadMyConfigSuccess: (state, { myConfig }) => myConfig?.task_defaults ?? state,
                saveTaskDefaultsDone: (state, { saved }) => saved ?? state,
            },
        ],
        taskDefaultsSaving: [
            false,
            {
                saveTaskDefaults: () => true,
                saveTaskDefaultsDone: () => false,
            },
        ],
    }),
    selectors({
        taskDefaults: [
            (s) => [s.lastTaskDefaults, s.myConfig],
            (
                lastTaskDefaults: TasksTaskDefaultsApi | null,
                myConfig: TasksUserConfigResponseApi | null
            ): TasksTaskDefaultsApi | null => lastTaskDefaults ?? myConfig?.task_defaults ?? null,
        ],
    }),
    listeners(({ actions, values }) => ({
        saveTaskDefaults: async ({ changes }) => {
            if (values.currentProjectId == null) {
                actions.saveTaskDefaultsDone(null)
                return
            }
            try {
                const saved = await tasksMeConfigTaskDefaultsCreate(String(values.currentProjectId), changes)
                lemonToast.success('Task defaults saved')
                actions.saveTaskDefaultsDone(saved)
            } catch {
                lemonToast.error('Your task defaults did not save. Try again.')
                actions.saveTaskDefaultsDone(null)
            }
        },
    })),
])
